mapper.sql:
WHERE deleted_at IS NULL

  AND category_id = #{categoryId}


  AND status IN
  #{status}



  AND id IN
  #{id}



  AND id NOT IN
  #{id}



  AND (status <> 'MANAGED' OR last_confirmed_on >= #{firstDayOfThisMonth})


  AND (status <> 'MANAGED' OR last_confirmed_on IS NULL OR last_confirmed_on < #{firstDayOfThisMonth})



  AND (LOWER(management_no) LIKE #{keywordPattern} ESCAPE '!'
    OR LOWER(maker) LIKE #{keywordPattern} ESCAPE '!'
    OR LOWER(model) LIKE #{keywordPattern} ESCAPE '!'
    OR LOWER(serial_no) LIKE #{keywordPattern} ESCAPE '!'

    OR id IN
    #{id}

  )
